INSERT INTO questions (code, topic, subtopic, difficulty, type, statement, options, answer_key, explanation, rubric, test_cases, follow_ups, time_estimate_sec, version, active) VALUES
('HR-001','HR','Introduction','EASY','LONG','Tell me about yourself and why you are interested in this role.',NULL,NULL,NULL,'[{"name":"Relevant background","keywords":["background","studied","degree","experience","worked","graduat"],"weight":1},{"name":"Skills and projects","keywords":["skill","technolog","built","project","learned"],"weight":1},{"name":"Motivation for the role","keywords":["interested","motivat","passion","excited","because i"],"weight":1},{"name":"Future goals","keywords":["goal","grow","future","looking to","aim"],"weight":1}]',NULL,'{"Motivation for the role":"What specifically about this role made you apply?","Skills and projects":"Which project best shows the skills this role needs?"}',240,1,TRUE),
('HR-002','HR','Teamwork','MEDIUM','LONG','Describe a time you disagreed with a teammate. What happened and how was it resolved?',NULL,NULL,NULL,'[{"name":"Situation","keywords":["situation","when we","project","team","was working"],"weight":1},{"name":"Your responsibility or goal","keywords":["responsib","goal","task","needed to","my role"],"weight":1},{"name":"Actions you took","keywords":["i decided","i talked","i proposed","i spoke","i listened","i suggested","i organized","i asked"],"weight":1},{"name":"Result","keywords":["result","outcome","as a result","resolved","delivered","improved"],"weight":1}]',NULL,'{"Actions you took":"What exactly did you do to resolve it, personally?","Result":"How did it end, and what changed afterwards?"}',300,1,TRUE),
('HR-003','HR','Failure','MEDIUM','LONG','Tell me about a mistake you made at work, study or a project and what you did about it.',NULL,NULL,NULL,'[{"name":"The mistake","keywords":["mistake","failed","wrong","error","missed"],"weight":1},{"name":"Taking ownership","keywords":["i took","my responsibility","i should","i owned","accountab","my fault"],"weight":1},{"name":"How it was fixed","keywords":["fixed","corrected","recover","rolled back","resolved","repaired"],"weight":1},{"name":"Lesson learned","keywords":["learned","lesson","now i","since then","process","changed how"],"weight":1}]',NULL,'{"Taking ownership":"What was your own part in it?","Lesson learned":"What do you do differently now because of it?"}',300,1,TRUE),
('HR-004','HR','Self-awareness','EASY','SHORT','What are your strengths and one weakness you are working on?',NULL,NULL,NULL,'[{"name":"A strength with an example","keywords":["strength","good at","for example","for instance","example"],"weight":1},{"name":"An honest weakness","keywords":["weakness","struggle","used to","tend to","not good"],"weight":1},{"name":"Steps to improve","keywords":["working on","course","practice","feedback","plan","improve"],"weight":1}]',NULL,'{"Steps to improve":"What concrete step have you taken to improve it?","A strength with an example":"Can you give an example where that strength made a difference?"}',180,1,TRUE),
('HR-005','HR','Pressure','MEDIUM','LONG','Tell me about a time you had to deliver under a tight deadline.',NULL,NULL,NULL,'[{"name":"Prioritisation","keywords":["priorit","most important","scope","trade","cut"],"weight":1},{"name":"Communication","keywords":["communicat","informed","told","stakeholder","manager","team"],"weight":1},{"name":"What you did","keywords":["worked","focused","delegat","plan","split","automated"],"weight":1},{"name":"Outcome","keywords":["deliver","met the deadline","result","shipped","outcome","on time"],"weight":1}]',NULL,'{"Prioritisation":"How did you decide what to leave out?","Communication":"Who did you keep informed, and how?"}',300,1,TRUE),
('HR-006','HR','Goals','EASY','SHORT','Where do you want to be in five years, and how does this role help?',NULL,NULL,NULL,'[{"name":"Growth intent","keywords":["grow","learn","skill","senior","lead","develop"],"weight":1},{"name":"Fit with the role or company","keywords":["company","role","team","contribute","value","opportunit"],"weight":1},{"name":"A realistic path","keywords":["step","plan","path","first","then","by"],"weight":1}]',NULL,'{"A realistic path":"What would the first year of that path look like?","Fit with the role or company":"How would you contribute to the team along the way?"}',180,1,TRUE),
('PRJ-001','PROJECT','Overview','MEDIUM','LONG','Describe a project you are proud of: the problem it solved, your role and the outcome.',NULL,NULL,NULL,'[{"name":"The problem","keywords":["problem","goal","needed","users","pain"],"weight":1},{"name":"Your role","keywords":["i built","i designed","i implemented","my role","i was responsible","i developed"],"weight":1},{"name":"Technology used","keywords":["stack","framework","database","api","react","spring","python","node","java"],"weight":1},{"name":"Outcome or impact","keywords":["result","outcome","deployed","users","impact","improved","launched"],"weight":1}]',NULL,'{"Your role":"Which part did you personally build, as opposed to your teammates?","Outcome or impact":"How did you know the project worked? Any numbers or feedback?"}',360,1,TRUE),
('PRJ-002','PROJECT','Design decisions','HARD','LONG','Walk me through the architecture of a project and one design trade-off you made.',NULL,NULL,NULL,'[{"name":"Components and layers","keywords":["architecture","component","service","layer","module","frontend","backend"],"weight":1},{"name":"A trade-off and the alternative","keywords":["trade-off","tradeoff","alternative","instead","chose","because"],"weight":1},{"name":"Data storage","keywords":["database","schema","cache","storage","table","index"],"weight":1},{"name":"Scalability or performance","keywords":["scale","load","performance","bottleneck","latency","concurrent"],"weight":1}]',NULL,'{"A trade-off and the alternative":"What alternative did you reject, and why?","Scalability or performance":"What would break first if usage grew tenfold?"}',420,1,TRUE),
('PRJ-003','PROJECT','Quality','MEDIUM','LONG','How did you test and maintain the quality of one of your projects?',NULL,NULL,NULL,'[{"name":"Kinds of tests","keywords":["unit test","integration","test","coverage","e2e"],"weight":1},{"name":"Automation and CI","keywords":["ci","pipeline","automated","github actions","jenkins"],"weight":1},{"name":"Debugging and monitoring","keywords":["bug","debug","logging","monitor","trace"],"weight":1},{"name":"Code review or standards","keywords":["review","lint","standard","pull request","format"],"weight":1}]',NULL,'{"Kinds of tests":"What did you choose to test, and what did you leave untested?","Debugging and monitoring":"Tell me about the hardest bug you found and how you found it."}',300,1,TRUE),
('PRJ-004','PROJECT','Challenges','MEDIUM','LONG','What was the hardest technical challenge in a project and how did you solve it?',NULL,NULL,NULL,'[{"name":"The challenge","keywords":["challenge","problem","issue","difficult","hard","stuck"],"weight":1},{"name":"How you investigated","keywords":["investigat","profil","logs","debug","reproduce","research","read the"],"weight":1},{"name":"The solution","keywords":["solution","fixed","implemented","approach","resolved","solved"],"weight":1},{"name":"What you learned","keywords":["learned","next time","would","lesson"],"weight":1}]',NULL,'{"How you investigated":"What did you try first, and what did that tell you?","What you learned":"What would you do differently next time?"}',300,1,TRUE),
('PRJ-005','PROJECT','Reflection','EASY','SHORT','If you rebuilt one of your projects today, what would you change and why?',NULL,NULL,NULL,'[{"name":"Specific changes","keywords":["would change","improve","refactor","redesign","replace","add"],"weight":1},{"name":"Reasons","keywords":["because","limitation","technical debt","bottleneck","hard to"],"weight":1},{"name":"Priorities","keywords":["first","priority","most important","then","start with"],"weight":1}]',NULL,'{"Reasons":"What problem in the current version motivates that change?","Priorities":"Which change would you make first?"}',200,1,TRUE),
('ML-001','ML','Fundamentals','EASY','MCQ','Which task is a classification problem?','[{"id":"A","text":"Predicting a house price"},{"id":"B","text":"Grouping customers with no labels"},{"id":"C","text":"Deciding whether an email is spam"},{"id":"D","text":"Reducing the number of features"}]','C','Classification predicts a discrete label such as spam / not spam.',NULL,NULL,NULL,45,1,TRUE),
('ML-002','ML','Generalisation','EASY','MCQ','A model reaches 99% accuracy on training data and 70% on validation data. What is the most likely cause?','[{"id":"A","text":"Underfitting"},{"id":"B","text":"Overfitting"},{"id":"C","text":"Too little training time"},{"id":"D","text":"Label noise only"}]','B','A large train/validation gap indicates the model memorised the training data.',NULL,NULL,NULL,60,1,TRUE),
('ML-003','ML','Evaluation','MEDIUM','MCQ','Which metric is most informative on a heavily imbalanced fraud dataset?','[{"id":"A","text":"Accuracy"},{"id":"B","text":"Precision and recall"},{"id":"C","text":"Mean squared error"},{"id":"D","text":"R-squared"}]','B','Accuracy is dominated by the majority class; precision and recall expose minority-class performance.',NULL,NULL,NULL,75,1,TRUE),
('ML-004','ML','Evaluation','MEDIUM','MCQ','What is the purpose of a validation set?','[{"id":"A","text":"To report the final unbiased performance"},{"id":"B","text":"To tune hyperparameters and choose between models"},{"id":"C","text":"To train the weights"},{"id":"D","text":"To increase the amount of data"}]','B','The validation set guides model selection; the test set is kept for the final estimate.',NULL,NULL,NULL,60,1,TRUE),
('ML-005','ML','Bias and variance','MEDIUM','SHORT','Explain the bias-variance trade-off.',NULL,NULL,NULL,'[{"name":"Bias and underfitting","keywords":["bias","underfit"],"weight":1},{"name":"Variance and overfitting","keywords":["variance","overfit"],"weight":1},{"name":"The trade-off with model complexity","keywords":["trade-off","tradeoff","balance","complexity"],"weight":1}]',NULL,'{"The trade-off with model complexity":"How does increasing model complexity change bias and variance?","Variance and overfitting":"How would you detect high variance in practice?"}',200,1,TRUE),
('ML-006','ML','Regularisation','MEDIUM','LONG','Compare L1 and L2 regularisation. When would you use each?',NULL,NULL,NULL,'[{"name":"Purpose: reduce overfitting","keywords":["overfit","penalt","regulariz"],"weight":1},{"name":"L1 gives sparse weights","keywords":["l1","lasso","sparse","zero"],"weight":1},{"name":"L2 shrinks weights","keywords":["l2","ridge","shrink","small weights"],"weight":1},{"name":"Strength hyperparameter","keywords":["lambda","alpha","strength","hyperparameter"],"weight":1}]',NULL,'{"L1 gives sparse weights":"Why does L1 tend to produce exactly-zero weights?","Strength hyperparameter":"How would you choose the regularisation strength?"}',300,1,TRUE),
('ML-007','ML','Optimisation','HARD','LONG','Explain gradient descent and the effect of the learning rate.',NULL,NULL,NULL,'[{"name":"Minimising a loss with gradients","keywords":["gradient","loss","minimi","steepest"],"weight":1},{"name":"The weight update step","keywords":["step","update","weights","subtract","negative gradient"],"weight":1},{"name":"Learning-rate effects","keywords":["learning rate","too large","diverge","too small","slow"],"weight":1},{"name":"Variants","keywords":["sgd","stochastic","mini-batch","batch","adam","momentum"],"weight":1}]',NULL,'{"Learning-rate effects":"What happens if the learning rate is too large? Too small?","Variants":"How does mini-batch SGD differ from full-batch gradient descent?"}',360,1,TRUE),
('ML-008','ML','Data handling','HARD','LONG','How do you split data and avoid data leakage when training a model?',NULL,NULL,NULL,'[{"name":"Train, validation and test splits","keywords":["train","validation","test"],"weight":1},{"name":"What data leakage is","keywords":["leak","leakage","test data","information"],"weight":1},{"name":"Cross-validation","keywords":["cross-validation","k-fold","kfold","cross validation"],"weight":1},{"name":"Fit preprocessing on training data only","keywords":["fit on","only on the training","scaler","pipeline","training data only"],"weight":1}]',NULL,'{"What data leakage is":"Can you give an example of leakage you could cause by accident?","Fit preprocessing on training data only":"Where in the pipeline should scaling be fitted, and why?"}',360,1,TRUE);
